CREATE TABLE IF NOT EXISTS qsa_return_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, return_no text NOT NULL, sales_order_id uuid, customer_id uuid, reason text NOT NULL, status text NOT NULL DEFAULT 'draft', requested_by uuid, workflow_instance_id uuid, idempotency_key text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_return_requests_org_idx ON qsa_return_requests(org_id);
CREATE INDEX IF NOT EXISTS qsa_return_requests_org_status_idx ON qsa_return_requests(org_id,status) ;
CREATE TABLE IF NOT EXISTS qsa_return_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, return_request_id uuid NOT NULL REFERENCES qsa_return_requests(id), item_id uuid, sku text, qty numeric(20,4) NOT NULL, condition text NOT NULL DEFAULT 'unopened', resolution text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_return_lines_org_idx ON qsa_return_lines(org_id);
CREATE TABLE IF NOT EXISTS qsa_promotions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, promo_code text NOT NULL, name text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz, customer_segment text, status text NOT NULL DEFAULT 'draft', budget_amount numeric(20,2), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_promotions_org_idx ON qsa_promotions(org_id);
CREATE INDEX IF NOT EXISTS qsa_promotions_org_status_idx ON qsa_promotions(org_id,status) ;
CREATE TABLE IF NOT EXISTS qsa_promotion_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, promotion_id uuid NOT NULL REFERENCES qsa_promotions(id), rule_type text NOT NULL, priority integer NOT NULL DEFAULT 100, conditions jsonb NOT NULL DEFAULT '{}'::jsonb, effects jsonb NOT NULL DEFAULT '{}'::jsonb, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_promotion_rules_org_idx ON qsa_promotion_rules(org_id);
CREATE TABLE IF NOT EXISTS qsa_sales_tenders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, tender_no text NOT NULL, customer_id uuid, deal_id uuid, title text NOT NULL, bid_value numeric(20,2), deadline_at timestamptz, status text NOT NULL DEFAULT 'draft', owner_id uuid, workflow_instance_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_sales_tenders_org_idx ON qsa_sales_tenders(org_id);
CREATE INDEX IF NOT EXISTS qsa_sales_tenders_org_status_idx ON qsa_sales_tenders(org_id,status) ;
CREATE TABLE IF NOT EXISTS qsa_tender_guarantees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, sales_tender_id uuid NOT NULL REFERENCES qsa_sales_tenders(id), guarantee_type text NOT NULL, guarantee_no text NOT NULL, issuer text, amount numeric(20,2) NOT NULL, valid_from date, valid_to date, status text NOT NULL DEFAULT 'issued', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_tender_guarantees_org_idx ON qsa_tender_guarantees(org_id);
CREATE INDEX IF NOT EXISTS qsa_tender_guarantees_org_status_idx ON qsa_tender_guarantees(org_id,status) ;
CREATE TABLE IF NOT EXISTS qsa_field_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, visit_no text NOT NULL, customer_id uuid, deal_id uuid, sales_rep_id uuid NOT NULL, planned_at timestamptz NOT NULL, location text, purpose text NOT NULL, status text NOT NULL DEFAULT 'planned', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_field_visits_org_idx ON qsa_field_visits(org_id);
CREATE INDEX IF NOT EXISTS qsa_field_visits_org_status_idx ON qsa_field_visits(org_id,status) ;
CREATE TABLE IF NOT EXISTS qsa_field_visit_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, field_visit_id uuid NOT NULL REFERENCES qsa_field_visits(id), outcome text NOT NULL, next_action text, followup_at timestamptz, competitor_notes text, attachments jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_field_visit_reports_org_idx ON qsa_field_visit_reports(org_id);
CREATE TABLE IF NOT EXISTS qsa_franchise_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, application_no text NOT NULL, customer_id uuid, applicant_name text NOT NULL, territory text NOT NULL, investment_capacity numeric(20,2), status text NOT NULL DEFAULT 'submitted', submitted_at timestamptz NOT NULL DEFAULT now(), workflow_instance_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_franchise_applications_org_idx ON qsa_franchise_applications(org_id);
CREATE INDEX IF NOT EXISTS qsa_franchise_applications_org_status_idx ON qsa_franchise_applications(org_id,status) ;
CREATE TABLE IF NOT EXISTS qsa_franchise_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, franchise_application_id uuid NOT NULL REFERENCES qsa_franchise_applications(id), reviewer_id uuid, review_stage text NOT NULL, score numeric(5,2), decision text NOT NULL DEFAULT 'pending', notes text, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_franchise_reviews_org_idx ON qsa_franchise_reviews(org_id);
CREATE TABLE IF NOT EXISTS qsa_import_shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, shipment_no text NOT NULL, customer_id uuid, supplier_id uuid, incoterm text, eta date, status text NOT NULL DEFAULT 'planned', customs_ref text, total_value numeric(20,2), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_import_shipments_org_idx ON qsa_import_shipments(org_id);
CREATE INDEX IF NOT EXISTS qsa_import_shipments_org_status_idx ON qsa_import_shipments(org_id,status) ;
CREATE TABLE IF NOT EXISTS qsa_export_shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, shipment_no text NOT NULL, customer_id uuid, sales_order_id uuid, destination_country text NOT NULL, etd date, eta date, status text NOT NULL DEFAULT 'planned', customs_ref text, total_value numeric(20,2), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_export_shipments_org_idx ON qsa_export_shipments(org_id);
CREATE INDEX IF NOT EXISTS qsa_export_shipments_org_status_idx ON qsa_export_shipments(org_id,status) ;
CREATE TABLE IF NOT EXISTS qsa_shipment_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, shipment_type text NOT NULL, shipment_id uuid NOT NULL, item_id uuid, description text NOT NULL, qty numeric(20,4) NOT NULL, uom text, declared_value numeric(20,2), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_shipment_lines_org_idx ON qsa_shipment_lines(org_id);
CREATE TABLE IF NOT EXISTS qsa_fulfillment_states(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, sales_order_id uuid NOT NULL, state text NOT NULL, state_version integer NOT NULL DEFAULT 1, source_module text NOT NULL DEFAULT 'qldn-sales-plus', changed_by uuid, changed_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_fulfillment_states_org_idx ON qsa_fulfillment_states(org_id);
CREATE INDEX IF NOT EXISTS qsa_fulfillment_states_org_status_idx ON qsa_fulfillment_states(org_id,state) ;
CREATE TABLE IF NOT EXISTS qsa_fulfillment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, fulfillment_state_id uuid NOT NULL REFERENCES qsa_fulfillment_states(id), event_type text NOT NULL, emitted_to text, idempotency_key text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_fulfillment_events_org_idx ON qsa_fulfillment_events(org_id);
CREATE TABLE IF NOT EXISTS qsa_customer_material_imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, import_no text NOT NULL, customer_id uuid, sales_order_id uuid, received_by uuid, received_at timestamptz, status text NOT NULL DEFAULT 'received', notes text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS qsa_customer_material_imports_org_idx ON qsa_customer_material_imports(org_id);
CREATE INDEX IF NOT EXISTS qsa_customer_material_imports_org_status_idx ON qsa_customer_material_imports(org_id,status) ;
CREATE UNIQUE INDEX IF NOT EXISTS qsa_return_requests_no_uq ON qsa_return_requests(org_id, return_no);
CREATE UNIQUE INDEX IF NOT EXISTS qsa_promotions_code_uq ON qsa_promotions(org_id, promo_code);
CREATE UNIQUE INDEX IF NOT EXISTS qsa_sales_tenders_no_uq ON qsa_sales_tenders(org_id, tender_no);
CREATE UNIQUE INDEX IF NOT EXISTS qsa_field_visits_no_uq ON qsa_field_visits(org_id, visit_no);
CREATE UNIQUE INDEX IF NOT EXISTS qsa_franchise_applications_no_uq ON qsa_franchise_applications(org_id, application_no);
CREATE UNIQUE INDEX IF NOT EXISTS qsa_import_shipments_no_uq ON qsa_import_shipments(org_id, shipment_no);
CREATE UNIQUE INDEX IF NOT EXISTS qsa_export_shipments_no_uq ON qsa_export_shipments(org_id, shipment_no);
CREATE UNIQUE INDEX IF NOT EXISTS qsa_fulfillment_states_order_version_uq ON qsa_fulfillment_states(org_id, sales_order_id, state_version);
CREATE UNIQUE INDEX IF NOT EXISTS qsa_fulfillment_events_idem_uq ON qsa_fulfillment_events(org_id, idempotency_key);
